use std::fs::File;
use std::io::Read;

use anyhow::{bail, Context, Result};
use unicodex_core::{
    cid_for_bytes, decode_node, encode_value_node, validate_cid, Node, ObjectStore, Value,
};

pub(super) fn load_exact_value(
    store: &ObjectStore,
    cid: &str,
    limit: usize,
    label: &'static str,
) -> Result<Value> {
    validate_cid(cid)?;
    let mut file = File::open(store.path_for(cid)?)
        .with_context(|| format!("{label} object is unavailable"))?;
    let mut bytes = Vec::new();
    (&mut file)
        .take((limit + 1) as u64)
        .read_to_end(&mut bytes)?;
    if bytes.len() > limit || cid_for_bytes(&bytes) != cid {
        bail!("{label} object is oversized or corrupt");
    }
    match decode_node(&bytes)? {
        Node::Value(value) if encode_value_node(&value)? == bytes => Ok(value),
        _ => bail!("{label} object is not an exact value"),
    }
}

pub(super) fn load_bounded_text(
    store: &ObjectStore,
    cid: &str,
    limit: usize,
    label: &'static str,
) -> Result<String> {
    match load_exact_value(store, cid, limit + 1024, label)? {
        Value::Text(value) if value.len() <= limit => Ok(value),
        _ => bail!("{label} ref is invalid or oversized"),
    }
}

